	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void nestedNativeValuesInvocationOwnsItsTelemetry(boolean interpreted) throws Exception {
		NativeLmdbQuerySource source = mock(NativeLmdbQuerySource.class, CALLS_REAL_METHODS);
		when(source.idSpace()).thenReturn(source);
		when(source.resultValueScope()).thenReturn(source);
		when(source.lazyValue(anyLong())).thenAnswer(invocation -> SimpleValueFactory.getInstance()
				.createIRI("urn:test:nested-telemetry:" + invocation.getArgument(0, Long.class)));
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("value", 0), null);
		layout.freeze(List.of("value"));
		SingletonSet outerTarget = telemetryTarget();
		SingletonSet innerTarget = telemetryTarget();
		SlotPlan innerValues = values(101L, 103L);
		List<List<List<Value>>> nestedRows = new ArrayList<>();
		SlotPlan outerPlan = new FilterPlan(values(2L, 4L, 7L), row -> {
			try {
				assertThat(row.id(0)).isIn(2L, 4L, 7L);
				nestedRows.add(execute(innerValues, source, layout, innerTarget, interpreted));
				return true;
			} catch (IOException failure) {
				throw new UncheckedIOException(failure);
			}
		}, 1L);

		List<List<Value>> outerRows = execute(outerPlan, source, layout, outerTarget, interpreted);
		List<Value> expectedOuter = List.of(value(2L), value(4L), value(7L));
		List<Value> expectedInner = List.of(value(101L), value(103L));
		assertThat(outerRows).containsExactlyElementsOf(expectedOuter.stream().map(List::of).toList());
		List<List<Value>> expectedInnerRows = expectedInner.stream().map(List::of).toList();
		assertThat(nestedRows).containsExactly(expectedInnerRows, expectedInnerRows, expectedInnerRows);

		String expectedRoute = interpreted ? LmdbNativeAttemptMetrics.PATH_IR_KERNEL_INTERPRETED
				: LmdbNativeAttemptMetrics.PATH_IR_KERNEL;
		assertOwnRuntimeTelemetry(outerTarget, expectedRoute, 3, 1);
		assertOwnRuntimeTelemetry(innerTarget, expectedRoute, 2, 1);
	}

	private static List<List<Value>> execute(SlotPlan plan, NativeLmdbQuerySource source, NativeSlotLayout layout,
			SingletonSet target, boolean interpreted) throws IOException {
		RowState row = new RowState(source, layout, EmptyBindingSet.getInstance(), target);
		assertThat(LmdbNativeAggregateCompiler.initializeRow(row, row.base, source, layout)).isTrue();
		row.runtimePlan = LmdbNativeExplain.recordRuntimeEntryPlan(target, plan, layout, row.boundMask());
		List<List<Value>> rows = new ArrayList<>();
		try (LmdbFusedSipFactorizedRuntime.Session invocation = LmdbFusedSipFactorizedRuntime.create(
				System.identityHashCode(plan), true)) {
			row.fusedSession = invocation;
			try (LmdbNativeStrategyProposal<RowCursor> proposal = LmdbNativeKernelExecution.proposeRows(plan, row,
					target, interpreted)) {
				assertThat(proposal).as("the explicitly requested real IR tier is admitted").isNotNull();
				String expectedRoute = interpreted ? LmdbNativeAttemptMetrics.PATH_IR_KERNEL_INTERPRETED
						: LmdbNativeAttemptMetrics.PATH_IR_KERNEL;
				assertThat(proposal.tag).as("the opened proposal names the requested IR tier").isEqualTo(expectedRoute);
				RowCursor cursor = proposal.open();
				assertThat(cursor).as("the real lowered VALUES IR opens").isNotNull();
				try (cursor) {
					while (cursor.next()) {
						rows.add(List.of(row.view.getValue("value")));
					}
				}
			} finally {
				invocation.recordMaterializationBoundary(rows.size());
				row.runtimePlan.fusedTelemetry(invocation.telemetry());
				row.closeDecodedInputs();
				row.completeRuntimePlan();
			}
		}
		return rows;
	}

	private static SlotPlan values(long... ids) {
		ValuesRow[] rows = new ValuesRow[ids.length];
		for (int index = 0; index < ids.length; index++) {
			rows[index] = new ValuesRow(new int[] { 0 }, new long[] { ids[index] });
		}
		return new ValuesPlan(rows);
	}

	private static SingletonSet telemetryTarget() {
		SingletonSet target = new SingletonSet();
		target.setRuntimeTelemetryEnabled(true);
		return target;
	}

	private static Value value(long id) {
		return SimpleValueFactory.getInstance().createIRI("urn:test:nested-telemetry:" + id);
	}

	private static void assertOwnRuntimeTelemetry(SingletonSet target, String route, int cardinality,
			int expectedBinds) {
		String telemetry = target.getStringMetricActual(TelemetryMetricNames.RUNTIME_PHYSICAL_PLAN);
		assertThat(telemetry).isNotNull();
		assertThat(telemetry).contains("route: " + route);
		assertThat(telemetry).contains("kernels:");
		assertThat(telemetry).contains("route=" + route + " binds=" + expectedBinds);
		assertThat(telemetry).contains("installedDomains: 1");
		assertThat(telemetry).contains("cardinalityUpperBound: " + cardinality);
	}
